using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Threading;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Tests;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

public class ProbeEveryGeneratedTypeDecoratedTests
{
    private const string TestSource = """
        using MessagePack;

        [MessagePackObject]
        public class ProbeObj
        {
            [Key(0)]
            public int Value { get; set; }
        }

        [MessagePackObject(keyAsPropertyName: true)]
        public class ProbeStringKeyObj
        {
            public string Name { get; set; }
        }

        public enum ProbeEnum
        {
            A,
            B,
        }

        [Union(0, typeof(ProbeUnionMember))]
        public interface IProbeUnion
        {
        }

        [MessagePackObject]
        public class ProbeUnionMember : IProbeUnion
        {
            [Key(0)]
            public int Value { get; set; }
        }

        namespace MessagePack
        {
            [GeneratedMessagePackResolver]
            partial class ProbeGeneratedResolver
            {
            }
        }
        """;

    [Fact]
    public async Task EveryGeneratedTypeIsDecorated()
    {
        ImmutableArray<MetadataReference> frameworkReferences = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);

        CSharpCompilation compilation = CSharpCompilation.Create(
            assemblyName: "ProbeEveryGeneratedTypeDecorated",
            syntaxTrees: [CSharpSyntaxTree.ParseText(TestSource, new CSharpParseOptions(LanguageVersion.Latest))],
            references: frameworkReferences.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver = (CSharpGeneratorDriver)driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out _);
        GeneratorDriverRunResult result = driver.GetRunResult();

        var failures = new List<string>();
        int checkedTypes = 0;
        foreach (SyntaxTree tree in result.GeneratedTrees)
        {
            CompilationUnitSyntax root = (CompilationUnitSyntax)tree.GetRoot();
            foreach (TypeDeclarationSyntax typeDeclaration in root.DescendantNodes().OfType<TypeDeclarationSyntax>())
            {
                checkedTypes++;
                bool decorated = typeDeclaration.AttributeLists
                    .SelectMany(list => list.Attributes)
                    .Any(attr => attr.Name.ToString().Contains("ExcludeFromCodeCoverage"));
                if (!decorated)
                {
                    FileLinePositionSpan span = typeDeclaration.GetLocation().GetLineSpan();
                    failures.Add($"{tree.FilePath}:{span.StartLinePosition.Line + 1}: {typeDeclaration.Kind()} {typeDeclaration.Identifier.Text}");
                }
            }
        }

        Assert.True(checkedTypes > 0, "Probe generated no types; test setup is broken.");
        Assert.True(failures.Count == 0, $"Checked {checkedTypes} generated types. Undecorated generated types:\n" + string.Join("\n", failures));
    }
}

