using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Threading;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Tests;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

public class ProbeEnumCollidingDeterminismTests
{
    private const string TestSource = """
        using MessagePack;

        namespace Ns1
        {
            public enum MyEnum
            {
                A,
                B,
            }
        }

        namespace Ns2
        {
            [MessagePackObject]
            public class Holder
            {
                [Key(0)]
                public Ns1.MyEnum Value { get; set; }
            }
        }
        """;

    [Fact]
    public async Task CollidingEnumNamesProduceDeterministicDecoratedOutput()
    {
        var outputs = new List<string>();
        for (int i = 0; i < 3; i++)
        {
            outputs.Add(await GenerateAsync());
        }

        Assert.Equal(outputs[0], outputs[1]);
        Assert.Equal(outputs[0], outputs[2]);
    }

    private static async Task<string> GenerateAsync()
    {
        ImmutableArray<MetadataReference> frameworkReferences = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);

        CSharpCompilation compilation = CSharpCompilation.Create(
            assemblyName: "ProbeEnumColliding",
            syntaxTrees: [CSharpSyntaxTree.ParseText(TestSource, new CSharpParseOptions(LanguageVersion.Latest))],
            references: frameworkReferences.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver = (CSharpGeneratorDriver)driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out _);
        GeneratorDriverRunResult result = driver.GetRunResult();

        return string.Join("\n=====\n", result.GeneratedTrees.OrderBy(t => t.FilePath, StringComparer.Ordinal).Select(t => t.FilePath + "\n" + t.GetText().ToString()));
    }
}

